drop policy if exists "favorites_owner" on public.favorites; drop policy if exists "event_rsvps_own_all" on public.event_rsvps; create policy "event_rsvps_own_all" on public.event_rsvps for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id and exists(select 1 from public.business_events e where e.id=event_rsvps.event_id and e.status in ('scheduled','active')));
